  'POST /api/payments/:id/:verb': ({ db, params, persona, reply }) => {
    const p = db.payments.find((x) => x.id === params.id);
    if (!p) return reply(404, { error: 'Payment not found' });
    if (params.verb !== 'approve' && params.verb !== 'reject') return reply(404, { error: 'Unknown action' });
    if (persona.role !== 'admin') return reply(403, { error: 'Only an admin can approve or reject payments.' });
    if (db.account.status === 'frozen') return reply(409, { error: 'This account is frozen. Payments are paused.' });
    if (p.status !== 'pending_approval') return reply(409, { error: `This payment is already ${p.status.replace('_', ' ')}.` });
    if (params.verb === 'approve' && db.account.spentThisMonth + p.amount > db.account.monthlyLimit) {
      return reply(409, { error: 'Approving this would go over the monthly spend limit.' });
    }
    p.status = params.verb === 'approve' ? 'approved' : 'rejected';
    if (p.status === 'approved') db.account.spentThisMonth = Math.round((db.account.spentThisMonth + p.amount) * 100) / 100;
    return p;
  },

  'POST /api/onboarding/complete-step': ({ db, persona, reply }) => {
    const u = db.users.find((x) => x.id === persona.userId);
    if (!u) return reply(401, { error: 'Not signed in' });
    u.onboardingStep = Math.min(ONBOARDING_STEPS, u.onboardingStep + 1);
    return { onboardingStep: u.onboardingStep };
  },

  // Agents live on a separate (fake) API host: https://api.ledgerly.example
  'GET /api/agents': ({ db }) => db.agents,

  'PATCH /api/agents/:id': ({ db, params, body, persona, reply }) => {
    const a = db.agents.find((x) => x.id === params.id);
    if (!a) return reply(404, { error: 'Agent not found' });
    if (persona.role !== 'admin') return reply(403, { error: 'Only an admin can change agents.' });
    if (body?.status === 'active' || body?.status === 'paused') a.status = body.status;
    return a;
  },
});

