  "title": "Pay a vendor, needs admin approval",
  "events": [
    { "type": "user_message", "text": "Pay Acme Supplies $4,200 for the November invoice." },
    { "type": "agent_message", "text": "Sure. Let me check the account and your spend limit first." },
    { "type": "tool_call", "id": "t1", "name": "get_account", "input": {} },
    { "type": "tool_result", "id": "t1", "output": { "status": "active", "spentThisMonth": 16340.2, "monthlyLimit": 25000 } },
    { "type": "agent_message", "text": "You have $8,659.80 left this month, so this fits. I'll draft the payment." },
    { "type": "tool_call", "id": "t2", "name": "create_payment", "input": { "vendor": "Acme Supplies", "amount": 4200 } },
    { "type": "tool_result", "id": "t2", "output": { "paymentId": "p9", "status": "pending_approval" } },
    {
      "type": "state_change",
      "patch": {
        "payments": {
          "$push": { "id": "p9", "vendor": "Acme Supplies", "amount": 4200, "status": "pending_approval", "requestedBy": "u2", "date": "2026-11-18" }
        }
      }
    },
    {
      "type": "pending_action",
      "id": "a1",
      "kind": "approve_payment",
      "title": "Approve $4,200 to Acme Supplies?",
      "data": { "paymentId": "p9", "vendor": "Acme Supplies", "amount": 4200 }
    },
    {
      "type": "branch",
      "cases": [
        { "when": { "path": "payments[id=p9].status", "equals": "approved" }, "goto": "approved" },
        { "when": { "path": "payments[id=p9].status", "equals": "rejected" }, "goto": "rejected" }
      ]
    }
  ],
  "branches": {
    "approved": [
      { "type": "agent_message", "text": "Approved. Acme Supplies will be paid today, and I've attached the invoice to the payment." }
    ],
    "rejected": [
      { "type": "agent_message", "text": "OK, I cancelled the payment to Acme Supplies. Nothing was sent." }
    ]
  }
}

